{
  "slug": "coins",
  "actions": [
    {
      "action": "computer_reply",
      "does": "Plays the computer's move on a row of coins and says which coin it took and why. `taken` is the moves already played, in order, each 'first' or 'last', starting with the human.",
      "exampleArgs": {
        "values": [
          4,
          2,
          9,
          1
        ],
        "taken": [
          "first"
        ]
      }
    },
    {
      "action": "parity_split",
      "does": "The two alternating colour classes of a row and their totals. On an even row the player who moves first can guarantee the larger of the two.",
      "exampleArgs": {
        "values": [
          4,
          2,
          9,
          1
        ]
      }
    },
    {
      "action": "play_out",
      "does": "Plays a whole game: the computer moves first, the human takes the given ends in order.",
      "exampleArgs": {
        "values": [
          4,
          2,
          9,
          1
        ],
        "humanChoices": [
          "first",
          "last"
        ]
      }
    }
  ]
}
